export interface ReplicaItem {
  id: string;
  value: string;
}

export interface ReplicaState {
  revision: number;
  items: readonly ReplicaItem[];
}

export type ReplicaChange =
  | { kind: "insert"; revision: number; item: ReplicaItem }
  | { kind: "delete"; revision: number; id: string }
  | { kind: "replace"; revision: number; items: readonly ReplicaItem[] };

function validRevision(value: number): boolean {
  return Number.isInteger(value) && value >= 0;
}

function copyItems(items: readonly ReplicaItem[]): ReplicaItem[] {
  const result = items.map((item) => ({ id: item.id.trim(), value: item.value }));
  if (result.some((item) => item.id.length === 0)) throw new RangeError("IDs must be non-blank");
  if (new Set(result.map((item) => item.id)).size !== result.length) throw new Error("Duplicate ID");
  return result;
}

export function applyReplicaChange(state: ReplicaState, change: ReplicaChange): ReplicaState {
  if (!validRevision(state.revision) || !validRevision(change.revision) || change.revision <= state.revision) {
    throw new RangeError("Invalid revision sequence");
  }
  const current = copyItems(state.items);
  let items: ReplicaItem[];
  if (change.kind === "insert") {
    const id = change.item.id.trim();
    if (id.length === 0) throw new RangeError("IDs must be non-blank");
    if (current.some((item) => item.id === id)) throw new Error("Duplicate ID");
    items = [...current, { id, value: change.item.value }];
  } else if (change.kind === "delete") {
    const id = change.id.trim();
    if (id.length === 0) throw new RangeError("IDs must be non-blank");
    if (!current.some((item) => item.id === id)) throw new Error("Missing ID");
    items = current.filter((item) => item.id !== id);
  } else {
    items = copyItems(change.items);
  }
  return { revision: change.revision, items };
}

