import { applyReplicaChange } from "./solution";
import type { ReplicaItem, ReplicaState, ReplicaChange } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function expectError(action: () => void, constructor: typeof Error): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof constructor, `expected ${constructor.name}`);
}
function ids(state: ReplicaState): string {
  return state.items.map((item) => item.id).join(",");
}

const originalItem: ReplicaItem = { id: "a", value: "A" };
const state: ReplicaState = { revision: 0, items: [originalItem] };
const insertedItem: ReplicaItem = { id: "b", value: "" };
const insert: ReplicaChange = { kind: "insert", revision: 1, item: insertedItem };
const afterInsert = applyReplicaChange(state, insert);
if (afterInsert.revision !== 1 || ids(afterInsert) !== "a,b") throw new Error("insert result incorrect");
if (afterInsert.items[1].value !== "") throw new Error("empty value was not preserved");
if (state.revision !== 0 || ids(state) !== "a") throw new Error("input state was mutated");
(insertedItem as { value: string }).value = "changed";
(originalItem as { value: string }).value = "changed-original";
if (afterInsert.items[0].value !== "A" || afterInsert.items[1].value !== "") throw new Error("result aliases input items");
(afterInsert.items as ReplicaItem[])[0] = { id: "x", value: "X" };
if (state.items[0].id !== "a") throw new Error("result array aliases state array");

const deleteState: ReplicaState = {
  revision: 4,
  items: [{ id: "a", value: "1" }, { id: "b", value: "2" }, { id: "c", value: "3" }],
};
const afterDelete = applyReplicaChange(deleteState, { kind: "delete", revision: 5, id: " b " });
if (ids(afterDelete) !== "a,c") throw new Error("delete did not preserve relative order");
const replacementItems: ReplicaItem[] = [{ id: "z", value: " Z " }, { id: "y", value: "Y" }];
const afterReplace = applyReplicaChange(afterDelete, { kind: "replace", revision: 6, items: replacementItems });
if (ids(afterReplace) !== "z,y" || afterReplace.items[0].value !== " Z ") throw new Error("replace order/value incorrect");
replacementItems[0].value = "changed";
replacementItems.pop();
if (afterReplace.items.length !== 2 || afterReplace.items[0].value !== " Z ") throw new Error("replace result aliases change");

expectError(() => applyReplicaChange({ revision: -1, items: [] }, { kind: "replace", revision: 0, items: [] }), RangeError);
expectError(() => applyReplicaChange({ revision: 0.5, items: [] }, { kind: "replace", revision: 1, items: [] }), RangeError);
expectError(() => applyReplicaChange({ revision: 0, items: [] }, { kind: "replace", revision: -1, items: [] }), RangeError);
expectError(() => applyReplicaChange({ revision: 0, items: [] }, { kind: "replace", revision: 1.5, items: [] }), RangeError);
expectError(() => applyReplicaChange({ revision: 2, items: [] }, { kind: "replace", revision: 4, items: [] }), RangeError);
expectError(() => applyReplicaChange({ revision: 0, items: [{ id: " ", value: "x" }] }, { kind: "delete", revision: 1, id: "x" }), RangeError);
expectError(() => applyReplicaChange({ revision: 0, items: [{ id: "a", value: "1" }, { id: " a ", value: "2" }] }, { kind: "replace", revision: 1, items: [] }), Error);
expectError(() => applyReplicaChange({ revision: 0, items: [{ id: "a", value: "1" }] }, { kind: "insert", revision: 1, item: { id: " a ", value: "2" } }), Error);
expectError(() => applyReplicaChange({ revision: 0, items: [] }, { kind: "delete", revision: 1, id: "missing" }), Error);
expectError(() => applyReplicaChange({ revision: 0, items: [] }, { kind: "replace", revision: 1, items: [{ id: "q", value: "1" }, { id: " q ", value: "2" }] }), Error);
expectError(() => applyReplicaChange({ revision: 0, items: [] }, { kind: "insert", revision: 1, item: { id: " ", value: "x" } }), RangeError);

const conflictState: ReplicaState = { revision: 0, items: [{ id: "a", value: "keep" }] };
const conflictChange: ReplicaChange = { kind: "insert", revision: 1, item: { id: "a", value: "new" } };
expectError(() => applyReplicaChange(conflictState, conflictChange), Error);
if (conflictState.items[0].value !== "keep" || conflictChange.item.value !== "new") throw new Error("conflict path mutated inputs");

